bool is_palindrome(const std::string& text) {
    std::string letters = "";
    for (const auto& letter : b2c::to_lower(text)) {
        if (letter != ' ') {
            letters = letters + std::string(1, letter);
        }
    }
    return letters == reversed(letters);
}

std::string reversed(const std::string& text) {
    std::string result = "";
    for (int i = static_cast<int>(text.size()) - 1; i >= 0; --i) {
        result = result + std::string(1, text.at(static_cast<std::size_t>(i)));
    }
    return result;
}

